let rpcId = 1;
async function rpc(url, method, params, timeout = 40000) {
  const controller = new AbortController(), timer = setTimeout(() => controller.abort(), timeout);
  try {
    const response = await fetch(url, { method: "POST", signal: controller.signal, headers: { "content-type": "application/json", "user-agent": "evm-audit-free-step3/1.0" }, body: JSON.stringify({ jsonrpc: "2.0", id: rpcId++, method, params }) });
    if (!response.ok) throw Object.assign(Error("RPC failed"), { status: response.status });
    const body = await response.json();
    if (body.error) throw Object.assign(Error(body.error.message || "RPC error"), { code: body.error.code, rpcData: body.error.data });
    return body.result;
  } finally { clearTimeout(timer); }
}
async function fetchJson(url, cap = 24 * 1024 * 1024) {
  const controller = new AbortController(), timer = setTimeout(() => controller.abort(), 50000);
  try {
    const response = await fetch(url, { signal: controller.signal, headers: { accept: "application/json", "user-agent": "evm-audit-free-step3/1.0" } });
    if (!response.ok) throw Object.assign(Error("GET failed"), { status: response.status });
    const chunks = []; let bytes = 0;
    for await (const chunk of response.body) { bytes += chunk.length; if (bytes > cap) throw Error("response-cap"); chunks.push(chunk); }
    return parse(Buffer.concat(chunks), "public provider response");
  } finally { clearTimeout(timer); }
}
