async function main(){let step2=null;try{step2=bindStep2();const step2Raw=parse(fs.readFileSync(STEP2_RAW),"Step2 raw"),provider=await selectProvider();if(fs.existsSync(SOURCE_ROOT))fs.rmSync(SOURCE_ROOT,{recursive:true,force:true});fs.mkdirSync(SOURCE_ROOT,{recursive:true});const historical=await historicalInitialSource(provider.url),catalog=signatureCatalog(historical.abi),analyzed=[];for(const target of TARGETS)analyzed.push(await collectImplementation(provider.url,target,catalog));const refs=[];for(const ref of REFERENCES){const runtime=await rpc(provider.url,"eth_getCode",[ref.address,PIN_HEX]),ins=disassemble(runtime);refs.push({...ref,runtime,ins,dispatch:dispatcher(ins)})}const comparisons=structuralComparisons(analyzed,refs),probesOut=[],histories=[],relations=[];for(let i=0;i<TARGETS.length;i++){const p=await probes(provider.url,TARGETS[i]);probesOut.push({id:TARGETS[i].id,...p});histories.push({id:TARGETS[i].id,...await directHistory(provider.url,TARGETS[i],step2Raw)});relations.push({id:TARGETS[i].id,...await safeRelation(provider.url,TARGETS[i],p.state)});}const core={step2,provider:provider.evidence,implementations:analyzed.map(x=>x.result),historicalInitialSource:{...historical,abi:undefined},structuralComparisons:comparisons,probes:probesOut,historicalDirectTransactions:histories,safeRelations:relations,candidates:candidateTable()};const runId=`free-step3-${hashCanonical(core).slice(0,20)}`,raw={schemaVersion:1,generatedAt:FIXED_MARKER,generatedAtQualification:"fixed structural marker; not retrieval time",runId,generationId:runId,classification:CLASSIFICATION,safety:{externalMutation:false,readOnlyOnly:true,providerUrlsEmitted:false,rawSignaturesPersisted:false,rawTransactionInputsPersisted:false,endpointInventoriesRead:false,environmentFilesRead:false,keyFilesRead:false,signing:false,broadcasts:false,forks:false,positiveValueCalls:false,methods:["GET","eth_chainId","eth_getBlockByNumber","eth_getCode","eth_getTransactionByHash","eth_getTransactionReceipt","eth_call","eth_getBalance"]},...core,gates:{route:false,execution:false,replay:false,vulnerabilityPromotion:false,lossProven:false,classificationSupported:analyzed.length===2&&analyzed.every(x=>x.result.sourceStatus.providerVerified===false)&&analyzed.every(x=>x.result.domainLiteral.offsets.length>0)&&comparisons.some(x=>x.atomicLockLineageEvidence)}};if(!raw.gates.classificationSupported)throw Error("conservative classification support gate failed");json(RAW,raw);atomic(REPORT,renderReport(raw));atomic(HANDOFF,renderHandoff(raw));writeManifest(runId);console.log(JSON.stringify({status:"ok",runId,classification:raw.classification,implementations:raw.implementations.length,selectors:raw.implementations.reduce((n,x)=>n+x.dispatcherSelectorCount,0),probes:raw.probes.reduce((n,x)=>n+x.rows.length,0),probeSuccess:raw.probes.reduce((n,x)=>n+x.rows.filter(y=>y.status==="success").length,0),probeRevert:raw.probes.reduce((n,x)=>n+x.rows.filter(y=>y.status==="revert").length,0),historicalTransactions:raw.historicalDirectTransactions.reduce((n,x)=>n+x.summary.transactions,0),effects:raw.historicalDirectTransactions.reduce((n,x)=>n+x.summary.erc20Transfers+x.summary.nativeTransfers,0),runtimeHashes:Object.fromEntries(raw.implementations.map(x=>[x.id,x.runtime.keccak256])),rawSha256:fileRecord(RAW).sha256,manifestSha256:fileRecord(MANIFEST).sha256,reportSha256:fileRecord(REPORT).sha256,handoffSha256:fileRecord(HANDOFF).sha256,blockers:["current source/ABI unverified","dynamic-jump dataflow bounded","no positive asset movement","no loss or replay proven"]},null,2));}
  catch(e){const reason=String(e.message||e).replace(/https?:\/\/\S+/g,"[redacted-url]");const runId=`free-step3-blocked-${sha256(Buffer.from(reason)).slice(0,16)}`;if(!fs.existsSync(SOURCE_ROOT))fs.mkdirSync(SOURCE_ROOT,{recursive:true});const raw={schemaVersion:1,generatedAt:FIXED_MARKER,runId,generationId:runId,classification:BLOCKED_CLASSIFICATION,safety:{externalMutation:false,providerUrlsEmitted:false,signing:false,broadcasts:false,forks:false,positiveValueCalls:false},step2,blocker:{reason},gates:{route:false,execution:false,replay:false,vulnerabilityPromotion:false,lossProven:false}};json(RAW,raw);atomic(REPORT,`# Free Protocol Step3 — blocked\n\n**${raw.classification}**\n\nExact blocker: ${reason}\n\nAll route/execution/replay/promotion/loss gates remain closed.\n`);atomic(HANDOFF,`# Coordinator handoff — Free Protocol Step3 blocked\n\nExact blocker: ${reason}\n\nNo coordinator state was edited; all gates remain closed.\n`);writeManifest(runId);console.error(JSON.stringify({status:"blocked",runId,reason,rawSha256:fileRecord(RAW).sha256,manifestSha256:fileRecord(MANIFEST).sha256},null,2));process.exitCode=1;}}

